import java.util.*;
import java.io.*;

public class Main {
    static final long INF = 0x7fffffffffffffffL;
    static final long MINF = -0x8000000000000000L;
    static final long MOD1 = 998244353L;
    static final long MOD2 = 1000000007L;

    static long totalN;
    static long totalCount;
    static long[] firstSum = new long[7];
    static List<Long>[] firstDigits = new ArrayList[7];

    static {
        for (int i = 0; i < 7; i++) {
            firstDigits[i] = new ArrayList<>();
        }
    }

    static boolean isPrime(long x) {
        if (x < 2) return false;
        long sqrtX = (long) Math.sqrt(x);
        for (long i = 2; i <= sqrtX; i++) {
            if (x % i == 0) return false;
        }
        return true;
    }

    static long readInput() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        return Long.parseLong(line.trim());
    }

    static long gcdValue(long x, long y) {
        return y == 0 ? x : gcdValue(y, x % y);
    }

    static long fastPow(long base, long exp, long mod) {
        long result = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }

    static void generateNumbers(int depth, long current) {
        if (depth > 6) return;
        long val = (totalCount - current + MOD1) % MOD1;
        firstDigits[depth].add(val);
        firstSum[depth] += val;
        totalCount++;
        for (int digit = 0; digit <= 9; digit++) {
            generateNumbers(depth + 1, current * 10 + digit);
        }
    }

    static long counter2 = -1;
    static long answer = 0;

    static void processNumbers(int depth, long current, long N) {
        if (current > N) return;
        if (current * 1000000 + 999999 <= N && current * 10000000 > N) {
            for (int i = 0; i <= 6; i++) {
                long shift = (counter2 + 1 - (current * fastPow(10, i, MOD1) % MOD1) + MOD1) % MOD1;
                List<Long> list = firstDigits[i];
                int pos = lowerBound(list, MOD1 - shift);
                long sumVal = firstSum[i] + shift * list.size() - MOD1 * (list.size() - pos);
                answer = (answer + sumVal) % MOD2;
            }
            counter2 += totalCount;
            return;
        }
        counter2++;
        answer = (answer + ((counter2 - current) % MOD1 + MOD1) % MOD1) % MOD2;
        for (int digit = 0; digit <= 9; digit++) {
            if (depth == 0 && digit == 0) continue;
            processNumbers(depth + 1, current * 10 + digit, N);
        }
    }

    static int lowerBound(List<Long> list, long value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        totalN = readInput();
        generateNumbers(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(firstDigits[i]);
        }
        processNumbers(0, 0, totalN);
        System.out.println(answer);
    }
}
